//! Host trace corpus: replay every case of `host_trace.json` (generated by running the Python
//! `PolicyHost` and `AuditLog`, see `prismpath/portable/gen_host_trace_fixtures.py`) through the Rust
//! host and require the same result for every operation, and byte for byte the same audit events,
//! leaves, Merkle root and state directory files. The clocks are counters, so timestamps are part of
//! the bytes; the work directory is written as `@ROOT@`.

mod common;

use common::{corpus, counter_clock, fresh_dir, pack_path, stage};
use prismpath_hotswap_rs::host::{merkle_root_and_paths, verify, verify_leaf, AuditLog, CommitStep, HostError, PolicyHost};
use prismpath_hotswap_rs::sha256_hex;
use prismpath_rs::durable::plain_dumps;
use serde_json::{json, Value};
use std::path::Path;
use std::sync::Arc;

const ROOT_MARK: &str = "@ROOT@";

fn canon(value: &Value) -> String {
    plain_dumps(value).expect("a value read from the corpus has a JSON form")
}

fn error_value(error: &HostError) -> Value {
    let mut out = json!({"raised": error.kind()});
    if let HostError::SwapRejected(reasons) = error {
        out["reasons"] = json!(reasons);
    }
    out
}

fn snapshot(state: &Path, root: &str) -> Value {
    let mut names: Vec<String> =
        std::fs::read_dir(state).unwrap().map(|entry| entry.unwrap().file_name().to_string_lossy().into_owned()).collect();
    names.sort();
    let mut files = serde_json::Map::new();
    for name in names {
        let path = state.join(&name);
        let value = if path.is_dir() {
            json!({"dir": true})
        } else if name.starts_with("active") && name.ends_with(".ppt") {
            json!({"sha256": sha256_hex(&std::fs::read(&path).unwrap())})
        } else {
            json!(String::from_utf8(std::fs::read(&path).unwrap()).unwrap().replace(root, ROOT_MARK))
        };
        files.insert(name, value);
    }
    Value::Object(files)
}

/// `{sha:NAME}` is the sha256 of pack NAME's image.
fn subst(doc: &Value, text: &str) -> String {
    let mut out = text.to_string();
    while let Some(start) = out.find("{sha:") {
        let end = start + out[start..].find('}').expect("an unclosed {sha:");
        let name = out[start + 5..end].to_string();
        out.replace_range(start..=end, doc["packs"][name.as_str()]["manifest"]["image_sha256"].as_str().unwrap());
    }
    out
}

fn fs_op(doc: &Value, state: &Path, packs: &Path, op: &Value) -> Value {
    let text = |key: &str| subst(doc, op[key].as_str().unwrap());
    let target = state.join(text("path"));
    let kind = op["do"].as_str().unwrap();
    match kind {
        "copy_pack" => std::fs::copy(packs.join(format!("{}.ppt", op["pack"].as_str().unwrap())), &target).map(|_| ()).unwrap(),
        "write" => std::fs::write(&target, text("text")).unwrap(),
        "append" => {
            use std::io::Write;
            let mut file = std::fs::OpenOptions::new().append(true).open(&target).unwrap();
            file.write_all(text("text").as_bytes()).unwrap();
        }
        "remove" => std::fs::remove_file(&target).unwrap(),
        "mkdir" => std::fs::create_dir(&target).unwrap(),
        "rmdir" => std::fs::remove_dir(&target).unwrap(),
        "rename" => std::fs::rename(&target, state.join(text("to"))).unwrap(),
        "replace" => {
            let contents = std::fs::read_to_string(&target).unwrap();
            let (old, new) = (subst(doc, op["old"].as_str().unwrap()), subst(doc, op["new"].as_str().unwrap()));
            assert!(contents.contains(&old));
            std::fs::write(&target, contents.replacen(&old, &new, 1)).unwrap();
        }
        "crlf" => std::fs::write(&target, std::fs::read_to_string(&target).unwrap().replace('\n', "\r\n")).unwrap(),
        other => panic!("unknown fs op {other}"),
    }
    json!({"done": kind})
}

fn verify_report(log: &AuditLog) -> Value {
    let persisted = match log.verify_persisted() {
        Ok(persisted) => persisted,
        Err(error) => return error_value(&error),
    };
    json!({
        "verify_log": log.verify_log(), "verify_persisted": persisted,
        "root": log.current_root(), "leaf_count": log.leaves().len(), "skipped": log.skipped(),
    })
}

fn inject(host: &PolicyHost, op: &Value) {
    if let Some(step) = op.get("fault").and_then(Value::as_str) {
        let step = CommitStep::from_name(step).unwrap_or_else(|| panic!("unknown commit step {step}"));
        host.set_commit_hook(Some(Box::new(move |reached| if reached == step { Err("injected".to_string()) } else { Ok(()) })));
    }
}

fn rollback_op(host: &PolicyHost, op: &Value) -> Value {
    inject(host, op);
    let result = host.rollback();
    host.set_commit_hook(None);
    result.unwrap_or_else(|error| error_value(&error))
}

fn swap_op(host: &PolicyHost, path: &str, op: &Value) -> Value {
    inject(host, op);
    let allow_unsigned = op.get("allow_unsigned").and_then(Value::as_bool).unwrap_or(false);
    let strict = op.get("strict").and_then(Value::as_bool).unwrap_or(false);
    let result = host.swap_with(path, allow_unsigned, strict);
    host.set_commit_hook(None);
    result.unwrap_or_else(|error| error_value(&error))
}

/// Replay one case; returns (per operation results, final log report, state directory files).
fn run_case(doc: &Value, case: &Value, work: &Path) -> (Vec<Value>, Value, Value) {
    let state = work.join("state");
    let pubs = stage(doc, work);
    let envelope = doc["envelopes"][case.get("envelope").and_then(Value::as_str).unwrap_or("default")].clone();
    let revoked: Vec<String> = case.get("revoked").map_or_else(Vec::new, |list| {
        list.as_array().unwrap().iter().map(|entry| entry.as_str().unwrap().to_string()).collect()
    });
    let clock = counter_clock(doc);
    let root = work.to_str().unwrap().to_string();
    let mut host: Option<Arc<PolicyHost>> = None;
    let mut results = Vec::new();
    for op in case["ops"].as_array().unwrap() {
        let kind = op["op"].as_str().unwrap();
        let live = || host.as_ref().expect("an operation before the first open");
        let result = match kind {
            "open" => match PolicyHost::new_with(state.to_str().unwrap(), pubs.clone(), envelope.clone(), revoked.clone(), None, clock.clone()) {
                Ok(opened) => {
                    let mut out = opened.active_info();
                    out["opened"] = json!(true);
                    host = Some(Arc::new(opened));
                    out
                }
                Err(error) => error_value(&error),
            },
            "swap" => swap_op(live(), &pack_path(work, op["pack"].as_str().unwrap()), op),
            "rollback" => rollback_op(live(), op),
            "append" => {
                // a `{"number_text": T}` value is the number the text T reads as, held as serde_json holds it
                let data: Vec<(&str, Value)> = op["data"]
                    .as_object()
                    .unwrap()
                    .iter()
                    .map(|(key, value)| {
                        let value = match value.get("number_text").and_then(Value::as_str) {
                            Some(text) => serde_json::from_str::<Value>(text).unwrap(),
                            None => value.clone(),
                        };
                        (&*Box::leak(key.clone().into_boxed_str()), value)
                    })
                    .collect();
                match live().audit.append("policy_host", op["action"].as_str().unwrap(), data) {
                    Ok(_) => json!({"appended": true}),
                    Err(error) => error_value(&HostError::Audit(error)),
                }
            }
            "attest" => live().attest().unwrap_or_else(|error| error_value(&error)),
            "active" => live().active_info(),
            "verify" => verify_report(&live().audit),
            "verify_prefix" => {
                let leaves = live().audit.leaves()[..op["count"].as_u64().unwrap() as usize].to_vec();
                let (root_hex, paths) = merkle_root_and_paths(&leaves);
                let root_hex = root_hex.unwrap_or_default();
                json!({
                    "root": root_hex,
                    "proofs": paths.iter().map(|path| json!({"path": path.iter().map(|(side, hash)| json!([side.to_string(), hash])).collect::<Vec<_>>(), "peaks": [root_hex]})).collect::<Vec<_>>(),
                    "verified": leaves.iter().zip(&paths).map(|(leaf, path)| verify(leaf, path, &root_hex)).collect::<Vec<_>>(),
                })
            }
            "prove" => {
                let host = live();
                match host.audit.prove(op["index"].as_i64().unwrap()) {
                    Some(proof) => {
                        let index = op["index"].as_u64().unwrap() as usize;
                        let verified = verify(&host.audit.leaves()[index], &proof.path, &host.audit.current_root());
                        json!({"proof": proof.to_value(), "verified": verified})
                    }
                    None => json!({"raised": "IndexError"}),
                }
            }
            "snapshot" => snapshot(&state, &root),
            "fs" => fs_op(doc, &state, &work.join("packs"), op),
            other => panic!("unknown op {other}"),
        };
        results.push(result);
    }
    let log_path = state.join("swaps.log");
    let final_report = if log_path.is_file() {
        let log = AuditLog::open_with(log_path.to_str().unwrap(), counter_clock(doc)).unwrap();
        let mut report = verify_report(&log);
        report["events"] = json!(log.events());
        report["leaves"] = json!(log.leaves());
        report
    } else {
        Value::Null
    };
    (results, final_report, snapshot(&state, &root))
}

#[test]
fn every_host_trace_case_replays_byte_identically() {
    let doc = corpus();
    let cases = doc["cases"].as_array().unwrap();
    assert!(cases.len() >= 30, "the corpus is not the one this test was written against");
    let mut operations = 0;
    let mut replayed = 0;
    for case in cases {
        // a case marked dev_build is a dev build's (spec-policy-distribution.md, D2), replayed only with the
        // `dev-hatches` feature, and every other case only without it
        if case["dev_build"].as_bool().unwrap_or(false) != prismpath_hotswap_rs::dist::DEV_BUILD {
            continue;
        }
        replayed += 1;
        let name = case["name"].as_str().unwrap();
        let work = fresh_dir(name);
        let (results, final_report, files) = run_case(&doc, case, &work);
        let expect = &case["expect"];
        let ops = case["ops"].as_array().unwrap();
        for (index, (op, (got, want))) in ops.iter().zip(results.iter().zip(expect["results"].as_array().unwrap())).enumerate() {
            assert_eq!(canon(got), canon(want), "{name}: operation {index} ({op})");
            operations += 1;
        }
        assert_eq!(results.len(), expect["results"].as_array().unwrap().len(), "{name}: operation count");
        assert_eq!(canon(&final_report), canon(&expect["final"]), "{name}: persisted log (events, leaves, root, skipped)");
        assert_eq!(canon(&files), canon(&expect["files"]), "{name}: state directory files");
    }
    assert!(replayed >= 2, "{replayed} cases for this build");
    eprintln!("host trace: {replayed}/{} cases, {operations} operations replayed byte identical to Python", cases.len());
}

/// The corpus must keep exercising what it exists to pin; a regeneration that drops a branch fails here.
#[test]
fn the_corpus_covers_the_protocol() {
    let doc = corpus();
    let mut actions = std::collections::BTreeSet::new();
    let mut raised = std::collections::BTreeSet::new();
    let mut reasons = std::collections::BTreeSet::new();
    let names: Vec<&str> = doc["cases"].as_array().unwrap().iter().map(|case| case["name"].as_str().unwrap()).collect();
    for step in doc["steps"].as_array().unwrap() {
        let wanted = format!("crash_{}_then_retry", step.as_str().unwrap());
        assert!(names.contains(&wanted.as_str()), "a crash case for {wanted}");
        assert!(CommitStep::from_name(step.as_str().unwrap()).is_some());
    }
    for step in doc["rollback_steps"].as_array().unwrap() {
        for kind in ["retry", "restart"] {
            let wanted = format!("crash_rollback_{}_then_{kind}", step.as_str().unwrap());
            assert!(names.contains(&wanted.as_str()), "a crash case for {wanted}");
        }
    }
    for wanted in ["audit_unwritable_on_rollback", "old_layout_is_read_then_migrated_by_a_swap", "old_layout_is_migrated_by_a_rollback",
        "stray_image_with_wrong_content_is_ignored_then_overwritten", "stray_images_are_collected_by_the_next_commit"] {
        assert!(names.contains(&wanted), "a case named {wanted}");
    }
    for case in doc["cases"].as_array().unwrap() {
        for result in case["expect"]["results"].as_array().unwrap() {
            if let Some(kind) = result.get("raised").and_then(Value::as_str) {
                raised.insert(kind.to_string());
            }
            for reason in result.get("reasons").and_then(Value::as_array).into_iter().flatten() {
                reasons.insert(reason.as_str().unwrap().to_string());
            }
        }
        for event in case["expect"]["final"].as_object().map_or(&vec![], |report| report["events"].as_array().unwrap()) {
            actions.insert(event["action"].as_str().unwrap_or("").to_string());
            for reason in event["data"].get("reasons").and_then(Value::as_array).into_iter().flatten() {
                reasons.insert(reason.as_str().unwrap().to_string());
            }
            if let Some(reason) = event["data"].get("reason").and_then(Value::as_str) {
                reasons.insert(reason.to_string());
            }
        }
    }
    for action in ["swap", "swap_rejected", "swap_incomplete", "rollback_incomplete", "rollback", "attestation", "active_unreadable"] {
        assert!(actions.contains(action), "no event of kind {action}");
    }
    for kind in ["AuditWriteError", "SwapRejected", "Injected", "IntentUnreadable", "OSError", "IndexError"] {
        assert!(raised.contains(kind), "no operation raised {kind}");
    }
    for reason in ["image:unreadable:2", "sig:invalid", "sig:revoked-key", "sig:missing", "envelope:unknown-field:z", "envelope:id-mismatch", "image:bad-magic", "image:digest-mismatch", "record:image-file-invalid", "image:unreadable:21", "version:not-monotonic:1<=2", "version:not-monotonic:2<=2", "rollback:no-previous"] {
        assert!(reasons.contains(reason), "no case reaches {reason}");
    }
}

/// Merkle proofs verify for every size of tree, in the way `audit_log.verify` checks them.
#[test]
fn merkle_proofs_verify_for_every_tree_size() {
    for count in 1..=17usize {
        let leaves: Vec<String> = (0..count).map(|index| sha256_hex(format!("leaf {index}").as_bytes())).collect();
        let (root, paths) = merkle_root_and_paths(&leaves);
        let root = root.unwrap();
        for (leaf, path) in leaves.iter().zip(&paths) {
            assert!(verify_leaf(leaf, path, &root), "{count} leaves");
            assert!(!verify_leaf(&sha256_hex(b"other"), path, &root), "{count} leaves, wrong leaf");
        }
    }
}
